arguments.command:
python -c "
from parse import Parser, FormatSpecError

# Test cases that should raise errors
error_cases = [
    '{abc',       # missing closing brace
    'abc}',       # unmatched closing brace  
    '{a{b}',      # nested braces
    '{}{',        # orphan {
    '{',          # just an open brace
    '}',          # just a close brace
    '{{{',        # escaped {{, then orphan {
    '}}{',        # escaped }}, then orphan {
]

print('Testing error cases:')
for tc in error_cases:
    try:
        p = Parser(tc)
        print(f'  FAIL: {repr(tc):20} -> No error (expression: {repr(p._expression)})')
    except FormatSpecError as e:
        print(f'  PASS: {repr(tc):20} -> FormatSpecError')
    except Exception as e:
        print(f'  FAIL: {repr(tc):20} -> Unexpected error: {type(e).__name__}: {e}')

# Test cases that should work
valid_cases = [
    '{abc}',       # valid field
    'hello {name} world',  # field with text
    '{{hello}}',   # escaped braces
    '{{abc',       # escaped {{ followed by literal abc
    'abc}}',       # literal abc followed by escaped }}
]

print('\nTesting valid cases:')
for tc in valid_cases:
    try:
        p = Parser(tc)
        print(f'  PASS: {repr(tc):30} -> expression: {repr(p._expression)}')
    except Exception as e:
        print(f'  FAIL: {repr(tc):30} -> Error: {type(e).__name__}: {e}')
" 2>&1 | grep -v SyntaxWarning
